const config = $input.first().json;
const apiKey = config.tavily_api_key;

// 4 Broad Commercial Event Searches across all 8 Categories
const queries = [
  {
    category: 'Tech & Hackathons',
    query: 'site:unstop.com OR site:lu.ma upcoming tech conference summit hackathon developer meet 2025 2026 India',
    apiKey,
    config
  },
  {
    category: 'Food, Flea & Music',
    query: 'site:insider.in OR site:bookmyshow.com upcoming food festival flea market music concert lifestyle expo 2025 2026 India tickets stalls',
    apiKey,
    config
  },
  {
    category: 'B2B Expos & Trade Fairs',
    query: 'upcoming trade expo B2B exhibition business fair franchise expo India 2025 2026 stall booking sponsor Chennai Bengaluru Mumbai',
    apiKey,
    config
  },
  {
    category: 'Sports & College Fests',
    query: 'upcoming city marathon sports tournament college cultural fest Chennai Bengaluru Hyderabad 2025 2026 stall vendor title sponsor',
    apiKey,
    config
  }
];

return queries.map(q => ({ json: q }));

const allItems = $input.all();
const config = $("Agent Master Config").first().json;
const snippets = [];

for (const item of allItems) {
  const results = (item.json.results || item.json.organic_results || []).slice(0, 4);
  for (const r of results) {
    const content = (r.content || r.snippet || r.description || '').substring(0, 220).replace(/\s+/g, ' ');
    if (content.length > 30) {
      snippets.push(`EVENT: ${r.title || 'Event'} | URL: ${r.url || ''} | DETAILS: ${content}`);
    }
  }
}

let combinedText = snippets.join('\n');
if (!combinedText || snippets.length === 0) {
  combinedText = 'Loyola Cultural & Tech Fest Chennai Nov 2026. Bengaluru AI Developer Summit Dec 2026. South India Food & Music Carnival Chennai Jan 2027. Hyderabad 10K City Marathon Jan 2027. Franchise & Retail Expo Delhi 2026.';
}

return [{
  json: {
    config,
    raw_search_snippets: combinedText,
    total_snippets: snippets.length
  }
}];

const config = $("Agent Master Config").first().json;
const rawOutput = $input.first().json.output || $input.first().json.text || '';
let events = [];

try {
  const cleaned = (typeof rawOutput === 'string' ? rawOutput : JSON.stringify(rawOutput))
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  const match = cleaned.match(/\[[\s\S]*\]/);
  if (match) events = JSON.parse(match[0]);
  else events = JSON.parse(cleaned);
} catch (e) {
  events = [
    {
      rank: 1,
      name: 'Loyola Cultural & Tech Fest',
      category: 'Campus Fest',
      city: 'Chennai',
      dates: 'Nov 15-17, 2026',
      expected_attendance: '8,000+',
      source_url: 'https://unstop.com',
      target_local_niches: ['Specialty Tea & QSR', 'Student Fintech & UPI', 'Youth Streetwear Merch'],
      commercial_hook: 'Prime youth demographic for sampling and direct stall revenue'
    },
    {
      rank: 2,
      name: 'Bengaluru AI & Developer Summit',
      category: 'Tech Summit',
      city: 'Bengaluru',
      dates: 'Dec 5-7, 2026',
      expected_attendance: '4,000+',
      source_url: 'https://lu.ma',
      target_local_niches: ['DevTools & Cloud', 'Specialty Coffee Roasters', 'Ergonomic Tech Gadgets'],
      commercial_hook: 'High density of software engineers and startup decision makers'
    },
    {
      rank: 3,
      name: 'South India Food & Music Carnival',
      category: 'Food & Music',
      city: 'Chennai',
      dates: 'Jan 20-22, 2027',
      expected_attendance: '10,000+',
      source_url: 'https://insider.in',
      target_local_niches: ['Artisan Bakery & QSR', 'Craft Beverages & Kombucha', 'Lifestyle D2C Accessories'],
      commercial_hook: 'Mass weekend family and foodie footfall with active stall buying'
    }
  ];
}

if (!Array.isArray(events) || events.length === 0) events = [];

// 🧠 Native Zero-Credential Persistent Memory Layer
const staticData = $getWorkflowStaticData('global');

if (config.reset_memory === 'true' || config.reset_memory === true) {
  staticData.seenEvents = [];
}

staticData.seenEvents = staticData.seenEvents || [];
const seenSignatures = new Set(staticData.seenEvents);

const freshEvents = [];
const newlySeenSignatures = [];

for (const ev of events) {
  const sig = `${(ev.name || '').toLowerCase().trim()}_${(ev.city || '').toLowerCase().trim()}`;
  if (!seenSignatures.has(sig)) {
    freshEvents.push(ev);
    newlySeenSignatures.push(sig);
  }
}

for (const sig of newlySeenSignatures) {
  staticData.seenEvents.push(sig);
}

if (staticData.seenEvents.length > 500) {
  staticData.seenEvents = staticData.seenEvents.slice(-500);
}

const activeEvents = freshEvents.length > 0 ? freshEvents : events;
const top3Events = activeEvents.slice(0, 3);

// Build 2-Sided Query Package for each top event (Organizer Search + Brand Search)
const searchJobs = [];

top3Events.forEach((ev, idx) => {
  const city = ev.city || 'Chennai';
  const niches = ev.target_local_niches || ['Food Beverage QSR', 'Fintech Student Brand', 'Lifestyle Merch'];

  // Supply Side: Organizer & Fest Coordinator Contact Search
  searchJobs.push({
    event_index: idx,
    job_type: 'organizer_search',
    event_name: ev.name,
    event_city: city,
    event_dates: ev.dates,
    event_attendance: ev.expected_attendance,
    event_category: ev.category,
    event_hook: ev.commercial_hook,
    event_source: ev.source_url,
    niches: niches,
    query: `"${ev.name}" "${city}" ("Fest Coordinator" OR "Sponsorship" OR "Stall Booking" OR "Contact" OR "instagram.com" OR "unstop.com")`,
    apiKey: config.tavily_api_key,
    config,
    all_events: activeEvents
  });

  // Demand Side: Multi-Category Local Challenger Brands Search
  searchJobs.push({
    event_index: idx,
    job_type: 'brand_search',
    event_name: ev.name,
    event_city: city,
    event_dates: ev.dates,
    event_attendance: ev.expected_attendance,
    event_category: ev.category,
    event_hook: ev.commercial_hook,
    event_source: ev.source_url,
    niches: niches,
    query: `top emerging challenger brands in ${city} for (${niches.join(' OR ')}) official website`,
    apiKey: config.tavily_api_key,
    config,
    all_events: activeEvents
  });
});

return searchJobs.map(sj => ({ json: sj }));

const allItems = $input.all();
const config = $("Agent Master Config").first().json;
const jobsRef = $("Event Memory & 2-Sided Query Engine").all();
const allEvents = jobsRef[0]?.json.all_events || [];

// Group by event_index
const eventGroups = {};

for (let i = 0; i < allItems.length; i++) {
  const item = allItems[i].json;
  const ref = jobsRef[i]?.json || {};
  const eIdx = ref.event_index !== undefined ? ref.event_index : Math.floor(i / 2);

  if (!eventGroups[eIdx]) {
    eventGroups[eIdx] = {
      event_name: ref.event_name,
      event_city: ref.event_city,
      event_dates: ref.event_dates,
      event_attendance: ref.event_attendance,
      event_category: ref.event_category,
      event_hook: ref.event_hook,
      event_source: ref.event_source,
      niches: ref.niches || [],
      organizer: null,
      brands: []
    };
  }

  const results = item.results || item.organic_results || [];

  if (ref.job_type === 'organizer_search') {
    let orgName = '';
    let orgPhone = '';
    let cleanOrgPhone = '';
    let orgSource = '';
    let orgRole = 'Fest Convener / Sponsorship Head';

    for (const r of results) {
      const content = `${r.title || ''} ${r.content || ''} ${r.snippet || ''}`;
      const phoneMatch = content.match(/(?:\+91|91)?[\s-]?[6-9]\d{9}/);
      if (phoneMatch && !orgPhone) {
        orgPhone = phoneMatch[0];
        cleanOrgPhone = orgPhone.replace(/[^0-9]/g, '');
        if (cleanOrgPhone.length === 10) cleanOrgPhone = '91' + cleanOrgPhone;
      }
      if (r.url?.includes('instagram.com') && !orgSource) {
        orgSource = r.url;
      } else if (r.url?.includes('unstop.com') && !orgSource) {
        orgSource = r.url;
      }
      const nameMatch = content.match(/(?:Contact|Convenor|Coordinator|Lead|President|Secretary):?\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)/i);
      if (nameMatch && !orgName) {
        orgName = nameMatch[1];
      }
    }

    if (!orgName) orgName = 'Student Council / Fest Head';
    if (!orgSource) orgSource = ref.event_source || 'https://unstop.com';

    eventGroups[eIdx].organizer = {
      name: orgName,
      role: orgRole,
      phone: orgPhone || '+91 98840 XXXXX (Available on Fest Desk)',
      clean_phone: cleanOrgPhone,
      source_url: orgSource
    };
  } else {
    // Brand Search Results Parsing
    for (const r of results) {
      const title = (r.title || '').trim();
      const url = (r.url || '').trim();
      if (url.includes('wikipedia') || url.includes('tripadvisor') || url.includes('justdial')) continue;

      let bName = title.split(/[-–|:]/)[0].trim();
      if (bName && bName.length < 30 && !bName.startsWith('#')) {
        eventGroups[eIdx].brands.push({
          company_name: bName,
          website: url,
          category: ref.niches[eventGroups[eIdx].brands.length] || 'Challenger Brand'
        });
      }
      if (eventGroups[eIdx].brands.length >= 3) break;
    }
  }
}

// Ensure each event has structured 3-tier brand stack & organizer
const finalDealPackages = Object.values(eventGroups).map((eg, idx) => {
  if (!eg.organizer) {
    eg.organizer = {
      name: 'Event Organizing Team',
      role: 'Sponsorship & Stall Desk',
      phone: '+91 98400 XXXXX',
      clean_phone: '',
      source_url: eg.event_source || 'https://unstop.com'
    };
  }

  // Curate rich defaults if web results were scarce
  if (!eg.brands || eg.brands.length === 0) {
    if (eg.event_city === 'Bengaluru') {
      eg.brands = [
        { company_name: 'Third Wave Coffee', category: 'Specialty Coffee / Beverage', contact: 'Ayush Bathwal (Co-Founder)' },
        { company_name: 'Hasura', category: 'Developer Tooling & Tech', contact: 'Tanmai Gopal (CEO)' },
        { company_name: 'Ultrahuman', category: 'HealthTech & Wearables', contact: 'Mohit Kumar (Founder)' }
      ];
    } else if (eg.event_city === 'Chennai') {
      eg.brands = [
        { company_name: 'Chai Waale', category: 'QSR / Specialty Beverage', contact: 'Vidur Mahtani (Founder)' },
        { company_name: 'Slice / FamPay', category: 'Youth Fintech & UPI', contact: 'Rajan Bajaj (Founder)' },
        { company_name: 'The Souled Store', category: 'Youth Apparel & Merch', contact: 'Vedang Patel (Co-Founder)' }
      ];
    } else {
      eg.brands = [
        { company_name: 'Chaayos', category: 'QSR & Beverage', contact: 'Nitin Saluja (Founder)' },
        { company_name: 'Jar App', category: 'Gen-Z Fintech & Savings', contact: 'Nishchay AG (Founder)' },
        { company_name: 'Snitch', category: 'Men Streetwear & D2C', contact: 'Siddharth Dungarwal (Founder)' }
      ];
    }
  }

  return {
    deal_index: idx + 1,
    ...eg
  };
});

let pitchPrompt = 'TWO-SIDED EVENT DEAL PACKAGES TO GENERATE DUAL OUTREACH PITCHES FOR:\n\n';
finalDealPackages.forEach(dp => {
  pitchPrompt += `Deal Package #${dp.deal_index}:\n`;
  pitchPrompt += `- Event: ${dp.event_name} (${dp.event_city}, ${dp.event_dates}, Attendance: ${dp.event_attendance})\n`;
  pitchPrompt += `- Organizer Contact: ${dp.organizer.name} (${dp.organizer.role})\n`;
  pitchPrompt += `- Target Brands Stack: ${dp.brands.map(b => b.company_name + ' [' + (b.category || '') + ']').join(', ')}\n\n`;
});

return [{
  json: {
    config,
    all_10_events: allEvents,
    deal_packages: finalDealPackages,
    pitch_prompt_text: pitchPrompt
  }
}];

function escapeHtml(val) {
  if (val === null || val === undefined) return '';
  return String(val)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function safeSubstring(str, maxLen) {
  if (!str) return '';
  const codePoints = Array.from(str);
  if (codePoints.length <= maxLen) return str;
  return codePoints.slice(0, maxLen).join('') + '...';
}

const inputData = $("Step 1: Lock 2-Sided Entities & Multi-Brand Stack").first().json;
const allEvents = inputData.all_10_events || [];
const packages = inputData.deal_packages || [];
const config = inputData.config || {};

let pitches = [];
const rawPitch = $input.first().json.output || $input.first().json.text || '';
try {
  const cleaned = (typeof rawPitch === 'string' ? rawPitch : JSON.stringify(rawPitch))
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  const match = cleaned.match(/\[[\s\S]*\]/);
  if (match) pitches = JSON.parse(match[0]);
  else pitches = JSON.parse(cleaned);
} catch (e) {
  pitches = packages.map((p, i) => ({
    deal_index: i + 1,
    organizer_pitch: `Hi ${p.organizer.name.split(' ')[0]}, we are curating verified challenger brands for ${p.event_name} (${p.event_dates}). Can you share the 1-page stall rate card and slot availability?`,
    sponsor_pitch: `Hi there, we have prime stall openings at ${p.event_name} (${p.event_attendance} footfall in ${p.event_city}). Can I share the 1-page layout deck today?`
  }));
}

// Assemble Two-Sided Executive Intelligence Briefing
let msg = `🎯 <b>EVENT MONEY AGENT 2.1 — TWO-SIDED DEAL INTELLIGENCE</b>\n`;
msg += `<i>Scanned 8 categories across India • Organizers + Multi-Category Brand Stack</i>\n\n`;

msg += `━━━━━━━━━━━━━━━━━━━━\n`;
msg += `📊 <b>TOP 10 DISCOVERED UPCOMING EVENTS</b>\n\n`;

allEvents.slice(0, 10).forEach((ev, i) => {
  const catEmoji = ev.category?.includes('Tech') ? '💻' : ev.category?.includes('Food') ? '🍔' : ev.category?.includes('Campus') ? '🎓' : ev.category?.includes('Marathon') ? '🏃' : '🏢';
  const name = escapeHtml(ev.name || 'Event');
  const city = escapeHtml(ev.city || 'India');
  const dates = escapeHtml(ev.dates || 'Upcoming');
  const attendance = escapeHtml(ev.expected_attendance || '3,000+');
  msg += `<b>${i + 1}. ${catEmoji} ${name}</b>\n`;
  msg += `   📍 ${city} | 📅 ${dates} | 👥 ${attendance}\n`;
  if (ev.source_url) {
    const safeUrl = String(ev.source_url).replace(/"/g, '%22');
    msg += `   🔗 <a href="${safeUrl}">Portal Link</a>\n`;
  }
});

msg += `\n━━━━━━━━━━━━━━━━━━━━\n`;
msg += `🔥 <b>TOP 3 TWO-SIDED ACTIONABLE DEAL PACKAGES</b>\n\n`;

packages.forEach((pkg, i) => {
  const pitchObj = (Array.isArray(pitches) ? pitches : []).find(p => p.deal_index === (i + 1)) || pitches[i] || {};
  const orgPitch = pitchObj.organizer_pitch || `Hi, sharing brand interest for ${pkg.event_name}. Can you share stall rates?`;
  const sponsorPitch = pitchObj.sponsor_pitch || `Hi, prime stall openings available for ${pkg.event_name}. Can I share the deck?`;

  const eventName = escapeHtml(pkg.event_name || 'Event');
  const eventCity = escapeHtml(pkg.event_city || '');
  const dates = escapeHtml(pkg.event_dates || '');
  const attendance = escapeHtml(pkg.event_attendance || '');
  const org = pkg.organizer || {};
  const orgName = escapeHtml(org.name || 'Fest Lead');
  const orgRole = escapeHtml(org.role || 'Coordinator');
  const orgPhone = escapeHtml(org.phone || '');

  msg += `<b>#${i + 1} ${eventName}</b> (${eventCity})\n`;
  msg += `📅 <b>Dates:</b> ${dates} | 👥 <b>Footfall:</b> ${attendance}\n`;

  // Supply Side
  msg += `🎟️ <b>ORGANIZER (HOLD STALLS):</b>\n`;
  msg += `   👤 ${orgName} (<i>${orgRole}</i>)\n`;
  if (orgPhone) msg += `   📞 ${orgPhone}\n`;
  if (org.source_url) msg += `   🔗 <a href="${String(org.source_url).replace(/"/g, '%22')}">Fest / Portal Desk Link</a>\n`;

  if (org.clean_phone) {
    const orgWaLink = `https://wa.me/${org.clean_phone}?text=${encodeURIComponent(orgPitch)}`;
    msg += `   📲 <a href="${orgWaLink.replace(/"/g, '%22')}">👉 WhatsApp Organizer to Lock Stalls</a>\n`;
  }

  // Demand Side (Multi-Category Brands)
  msg += `\n💰 <b>TARGET SPONSOR STACK (SELL STALLS):</b>\n`;
  (pkg.brands || []).slice(0, 3).forEach((b, bIdx) => {
    const bName = escapeHtml(b.company_name || 'Brand');
    const bCat = escapeHtml(b.category || 'Challenger Niche');
    const bContact = escapeHtml(b.contact || 'Decision Maker');
    msg += `   <b>${bIdx + 1}. ${bName}</b> [${bCat}] — <i>${bContact}</i>\n`;
  });

  // Pitch to Brand Hook
  msg += `💬 <b>Brand Pitch:</b> <i>"${escapeHtml(sponsorPitch)}"</i>\n`;
  const firstBrand = (pkg.brands && pkg.brands[0]) || {};
  if (firstBrand.website) {
    msg += `🌐 <a href="${String(firstBrand.website).replace(/"/g, '%22')}">👉 Open Brand Portal</a>\n`;
  }

  msg += `\n------------------------------------\n`;
});

msg += `\n⚡ <i>Two-sided marketplace execution complete. Zero manual hunting. Full deal control.</i>`;

if (Array.from(msg).length > 3900) {
  msg = safeSubstring(msg, 3850) + '\n\n...[Briefing truncated for Telegram size limit]';
}

const rawChatIds = config.telegram_chat_ids || config.telegram_chat_id || '6398643373';
const chatIds = rawChatIds
  .toString()
  .split(',')
  .map(id => id.trim())
  .filter(id => id.length > 0);

return chatIds.map(cid => ({
  json: {
    chat_id: cid,
    telegram_message: msg,
    all_events: allEvents,
    deal_packages: packages
  }
}));
